+using System;
+using System.Collections.Generic;
+
+namespace HarnessTestBed.Data
+{
+    public class Inventory
+    {
+        private readonly List<string> _itemIds;
+        public int MaxCapacity { get; }
+        public int Count => _itemIds.Count;
+        public bool IsFull => _itemIds.Count >= MaxCapacity;
+        public IReadOnlyList<string> ItemIds => _itemIds;
+
+        public Inventory(int maxCapacity)
+        {
+            if (maxCapacity <= 0)
+                throw new ArgumentOutOfRangeException(nameof(maxCapacity),
+                    maxCapacity, "Capacity must be greater than zero.");
+            MaxCapacity = maxCapacity;
+            _itemIds = new List<string>(maxCapacity);
+        }
+
+        public bool TryAddItem(string itemId)
+        {
+            if (string.IsNullOrEmpty(itemId))
+                throw new ArgumentNullException(nameof(itemId), "Item ID must not be null or empty.");
+            if (IsFull) return false;
+            if (_itemIds.Contains(itemId)) return false;
+            _itemIds.Add(itemId);
+            return true;
+        }
+
+        public bool RemoveItem(string itemId)
+        {
+            if (string.IsNullOrEmpty(itemId))
+                throw new ArgumentNullException(nameof(itemId), "Item ID must not be null or empty.");
+            return _itemIds.Remove(itemId);
+        }
+
+        public bool Contains(string itemId) => _itemIds.Contains(itemId);
+    }
+}
