+using System;
+using System.Collections.Generic;
+using Unity.Netcode;
+using HarnessTestBed.Data;
+
+namespace HarnessTestBed.Player
+{
+    public class PlayerInventory : NetworkBehaviour
+    {
+        private readonly NetworkList<Unity.Collections.FixedString64Bytes> _networkItems = new();
+        private Inventory _inventory;
+
+        [UnityEngine.SerializeField] private int maxCapacity = 20;
+
+        public IReadOnlyList<string> ItemIds => _inventory.ItemIds;
+        public event Action<IReadOnlyList<string>> OnInventoryChanged;
+
+        private void Awake() { _inventory = new Inventory(maxCapacity); }
+
+        public override void OnNetworkSpawn()
+        {
+            base.OnNetworkSpawn();
+            _networkItems.OnListChanged += HandleNetworkListChanged;
+            SyncFromNetwork();
+        }
+
+        public override void OnNetworkDespawn()
+        {
+            _networkItems.OnListChanged -= HandleNetworkListChanged;
+            base.OnNetworkDespawn();
+        }
+
+        public bool TryAddItem(string itemId)
+        {
+            if (!IsOwner) throw new InvalidOperationException("Only the owner can modify inventory.");
+            if (!_inventory.TryAddItem(itemId)) return false;
+            _networkItems.Add(new Unity.Collections.FixedString64Bytes(itemId));
+            OnInventoryChanged?.Invoke(_inventory.ItemIds);
+            return true;
+        }
+
+        private void HandleNetworkListChanged(NetworkListEvent<Unity.Collections.FixedString64Bytes> evt)
+        {
+            if (!IsOwner) SyncFromNetwork();
+        }
+
+        private void SyncFromNetwork()
+        {
+            _inventory = new Inventory(maxCapacity);
+            foreach (var item in _networkItems) _inventory.TryAddItem(item.ToString());
+            OnInventoryChanged?.Invoke(_inventory.ItemIds);
+        }
+    }
+}
